import React from 'react'
import { useDropdown } from '@/hooks'
import ToggleButton from '../ui/button/ToogelButton'

interface BaseItem {
  title: string
  id?: string | number
}

interface DropdownProps<T extends BaseItem> {
  items: T[]
  label: string
  className: string
  onSelect: (item: T) => void
  renderItem?: (item: T, isActive: boolean) => React.ReactNode
}

export const Dropdown = <T extends BaseItem>({
  items,
  label,
  className,
  onSelect,
  renderItem,
}: DropdownProps<T>) => {
  const {
    isOpen,
    activeIndex,
    toggleDropdown,
    handleKeyDown,
    comboboxRef,
    listboxRef,
    optionRefs,
    setActiveIndex,
  } = useDropdown({
    items,
    onSelect,
  })

  return (
    <div className="relative" ref={comboboxRef}>
      <ToggleButton
        label={label}
        className={className}
        isOpen={isOpen}
        toggleDropdown={() => {
          toggleDropdown()
          if (!isOpen) {
            setActiveIndex(0)
          }
        }}
        onKeyDown={handleKeyDown}
      />

      {isOpen && (
        <ul
          role="listbox"
          ref={listboxRef}
          aria-labelledby="combo-label"
          tabIndex={-1}
          className="absolute z-10 w-full overflow-y-auto rounded-b-md border-b border-l border-r border-gray-200 bg-white text-lg"
        >
          {items.map((item, index) => (
            <li
              key={index}
              ref={(el) => (optionRefs.current[index] = el)}
              role="option"
              aria-selected={index === activeIndex}
              className={`px-4 py-3 hover:text-gray-500 ${index === activeIndex ? 'bg-gray-100' : ''}`}
              onClick={() => {
                onSelect(item)
                toggleDropdown()
              }}
            >
              {renderItem
                ? renderItem(item, index === activeIndex)
                : item.title}
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

