import React from 'react'
import { UserMenu } from '@/types/header'
import Link from 'next/link'
import { logoutUser } from '@/apis/action/auth'
import { useRouter } from 'next/navigation'
import { Dropdown } from './Dropdown'

interface UserDropdownProps {
  items: UserMenu[]
  label: string
  className: string
}

export const UserDropdown = ({
  items,
  label,
  className,
}: UserDropdownProps) => {
  const router = useRouter()

  const handleLogout = async () => {
    const { message, success } = await logoutUser()
    if (success) {
      alert(message)
      router.push('/')
    }
  }

  const handleSelect = (item: UserMenu) => {
    if (item.path) {
      router.push(item.path)
    } else {
      handleLogout()
    }
  }

  const renderUserMenuItem = (item: UserMenu) => {
    if (item.path) {
      return <Link href={item.path}>{item.title}</Link>
    }
    return <button onClick={handleLogout}>{item.title}</button>
  }

  return (
    <Dropdown
      items={items}
      label={label}
      className={className}
      onSelect={handleSelect}
      renderItem={renderUserMenuItem}
    />
  )
}

